/* eslint-disable space-in-parens */

import Complex128Array = require( '@stdlib/array/complex128' );
import znone = require( './index' );


// TESTS //

// The function returns a boolean...
{
	const x = new Complex128Array( 10 );

	znone( x.length, x, 1 ); // $ExpectType boolean
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );

	znone( '10', x, 1 ); // $ExpectError
	znone( true, x, 1 ); // $ExpectError
	znone( false, x, 1 ); // $ExpectError
	znone( null, x, 1 ); // $ExpectError
	znone( undefined, x, 1 ); // $ExpectError
	znone( [], x, 1 ); // $ExpectError
	znone( {}, x, 1 ); // $ExpectError
	znone( ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );

	znone( x.length, '10', 1 ); // $ExpectError
	znone( x.length, true, 1 ); // $ExpectError
	znone( x.length, false, 1 ); // $ExpectError
	znone( x.length, null, 1 ); // $ExpectError
	znone( x.length, undefined, 1 ); // $ExpectError
	znone( x.length, [], 1 ); // $ExpectError
	znone( x.length, {}, 1 ); // $ExpectError
	znone( x.length, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Complex128Array( 10 );

	znone( x.length, x, '1' ); // $ExpectError
	znone( x.length, x, true ); // $ExpectError
	znone( x.length, x, false ); // $ExpectError
	znone( x.length, x, null ); // $ExpectError
	znone( x.length, x, undefined ); // $ExpectError
	znone( x.length, x, [] ); // $ExpectError
	znone( x.length, x, {} ); // $ExpectError
	znone( x.length, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );

	znone(); // $ExpectError
	znone( x.length ); // $ExpectError
	znone( x.length, x ); // $ExpectError
	znone( x.length, x, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a boolean...
{
	const x = new Complex128Array( 10 );

	znone.ndarray( x.length, x, 1, 0 ); // $ExpectType boolean
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );

	znone.ndarray( '10', x, 1, 0 ); // $ExpectError
	znone.ndarray( true, x, 1, 0 ); // $ExpectError
	znone.ndarray( false, x, 1, 0 ); // $ExpectError
	znone.ndarray( null, x, 1, 0 ); // $ExpectError
	znone.ndarray( undefined, x, 1, 0 ); // $ExpectError
	znone.ndarray( [], x, 1, 0 ); // $ExpectError
	znone.ndarray( {}, x, 1, 0 ); // $ExpectError
	znone.ndarray( ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );

	znone.ndarray( x.length, '10', 1, 0 ); // $ExpectError
	znone.ndarray( x.length, true, 1, 0 ); // $ExpectError
	znone.ndarray( x.length, false, 1, 0 ); // $ExpectError
	znone.ndarray( x.length, null, 1, 0 ); // $ExpectError
	znone.ndarray( x.length, undefined, 1, 0 ); // $ExpectError
	znone.ndarray( x.length, [], 1, 0 ); // $ExpectError
	znone.ndarray( x.length, {}, 1, 0 ); // $ExpectError
	znone.ndarray( x.length, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const x = new Complex128Array( 10 );

	znone.ndarray( x.length, x, '1', 0 ); // $ExpectError
	znone.ndarray( x.length, x, true, 0 ); // $ExpectError
	znone.ndarray( x.length, x, false, 0 ); // $ExpectError
	znone.ndarray( x.length, x, null, 0 ); // $ExpectError
	znone.ndarray( x.length, x, undefined, 0 ); // $ExpectError
	znone.ndarray( x.length, x, [], 0 ); // $ExpectError
	znone.ndarray( x.length, x, {}, 0 ); // $ExpectError
	znone.ndarray( x.length, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const x = new Complex128Array( 10 );

	znone.ndarray( x.length, x, 1, '0' ); // $ExpectError
	znone.ndarray( x.length, x, 1, true ); // $ExpectError
	znone.ndarray( x.length, x, 1, false ); // $ExpectError
	znone.ndarray( x.length, x, 1, null ); // $ExpectError
	znone.ndarray( x.length, x, 1, undefined ); // $ExpectError
	znone.ndarray( x.length, x, 1, [] ); // $ExpectError
	znone.ndarray( x.length, x, 1, {} ); // $ExpectError
	znone.ndarray( x.length, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );

	znone.ndarray(); // $ExpectError
	znone.ndarray( x.length ); // $ExpectError
	znone.ndarray( x.length, x ); // $ExpectError
	znone.ndarray( x.length, x, 1 ); // $ExpectError
	znone.ndarray( x.length, x, 1, 0, {} ); // $ExpectError
}
